'use client';

import React, { useState } from 'react';
import ActionHub from '@/components/ActionHub';
import { Search, Filter, MoreHorizontal, Circle } from 'lucide-react';

// Mock Data for Phase 1 UI
const MOCK_SESSIONS = Array.from({ length: 20 }).map((_, i) => ({
  id: `sess_${i}`,
  plate: `ABC-${100 + i}`,
  mobile: i % 3 === 0 ? '+1 (555) 000-0000' : 'N/A',
  name: i % 3 === 0 ? 'John Doe' : 'Guest',
  status: i % 4 === 0 ? 'expired' : 'active',
  entry: new Date(Date.now() - i * 1000 * 60 * 30).toLocaleTimeString(),
  duration: `${30 + i * 10} min`,
  payment: i % 4 === 0 ? 'pending' : 'paid',
}));

export default function DashboardPage() {
  const [filter, setFilter] = useState<'all' | 'active' | 'expired'>('all');

  return (
    <div className="min-h-full bg-background text-white p-6 pb-32">
      {/* Header / Stats */}
      <div className="flex justify-between items-end mb-6">
        <div>
          <h2 className="text-2xl font-bold tracking-tight">Live Operations</h2>
          <p className="text-white/50 text-sm">Zone A-12 • {MOCK_SESSIONS.length} Active Sessions</p>
        </div>
        <div className="flex gap-2">
          <div className="bg-surface border border-white/10 px-4 py-2 rounded">
            <div className="text-xs text-white/50 uppercase">Occupancy</div>
            <div className="text-xl font-bold text-primary">84%</div>
          </div>
          <div className="bg-surface border border-white/10 px-4 py-2 rounded">
            <div className="text-xs text-white/50 uppercase">Revenue (24h)</div>
            <div className="text-xl font-bold text-green-400">$1,240</div>
          </div>
        </div>
      </div>

      {/* Toolbar */}
      <div className="flex gap-4 mb-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-2.5 text-white/30" size={16} />
          <input 
            type="text" 
            placeholder="Search Plate, Mobile, or ID..." 
            className="w-full bg-surface border border-white/10 rounded pl-10 pr-4 py-2 text-sm focus:outline-none focus:border-primary"
          />
        </div>
        <div className="flex bg-surface border border-white/10 rounded p-1 gap-1">
          {['all', 'active', 'expired'].map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f as any)}
              className={`px-4 py-1.5 rounded text-xs font-medium uppercase transition-colors ${
                filter === f ? 'bg-primary text-white' : 'text-white/50 hover:text-white'
              }`}
            >
              {f}
            </button>
          ))}
        </div>
      </div>

      {/* High Density Table */}
      <div className="bg-surface border border-white/10 rounded-lg overflow-hidden">
        <table className="w-full text-left text-sm">
          <thead className="bg-black/20 text-white/50 uppercase text-[10px] tracking-wider">
            <tr>
              <th className="px-4 py-3 font-medium">Status</th>
              <th className="px-4 py-3 font-medium">Plate</th>
              <th className="px-4 py-3 font-medium">Entry Time</th>
              <th className="px-4 py-3 font-medium">Duration</th>
              <th className="px-4 py-3 font-medium">Mobile / Name</th>
              <th className="px-4 py-3 font-medium">Payment</th>
              <th className="px-4 py-3 font-medium text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5">
            {MOCK_SESSIONS.map((session) => (
              <tr key={session.id} className="hover:bg-white/5 transition-colors group cursor-pointer">
                <td className="px-4 py-2">
                  <div className={`flex items-center gap-2 ${session.status === 'active' ? 'text-green-400' : 'text-red-400'}`}>
                    <Circle size={8} fill="currentColor" />
                    <span className="uppercase font-bold text-[10px]">{session.status}</span>
                  </div>
                </td>
                <td className="px-4 py-2 font-mono text-white font-bold tracking-wide">
                  {session.plate}
                </td>
                <td className="px-4 py-2 text-white/70">
                  {session.entry}
                </td>
                <td className="px-4 py-2 text-white/70">
                  {session.duration}
                </td>
                <td className="px-4 py-2">
                  <div className="flex flex-col">
                    <span className="text-white">{session.mobile}</span>
                    <span className="text-[10px] text-white/40">{session.name}</span>
                  </div>
                </td>
                <td className="px-4 py-2">
                  <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-medium uppercase ${
                    session.payment === 'paid' ? 'bg-green-500/10 text-green-400' : 'bg-yellow-500/10 text-yellow-400'
                  }`}>
                    {session.payment}
                  </span>
                </td>
                <td className="px-4 py-2 text-right">
                  <button className="text-white/30 hover:text-white p-1">
                    <MoreHorizontal size={16} />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <ActionHub />
    </div>
  );
}
