'use client';

import React from 'react';
import { Camera, Upload, AlertTriangle, FileText } from 'lucide-react';

export default function ActionHub() {
  const handleAction = (action: string) => {
    console.log(`Action triggered: ${action}`);
    // In Phase 1, this might just log or show a toast
    alert(`Triggered: ${action}`);
  };

  return (
    <div className="fixed bottom-6 left-72 z-50 flex gap-4">
      <div className="flex flex-col gap-2 bg-surface/90 backdrop-blur border border-white/10 p-2 rounded-lg shadow-xl">
        <div className="text-[10px] font-bold text-white/50 uppercase tracking-wider text-center">
          Tactical Hub
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => handleAction('SCANNER')}
            className="flex flex-col items-center justify-center w-20 h-20 bg-black/40 hover:bg-primary/20 border border-white/10 hover:border-primary text-white rounded transition-all group"
          >
            <Camera size={24} className="mb-1 group-hover:scale-110 transition-transform" />
            <span className="text-[10px] font-bold">LPR HUD</span>
          </button>
          
          <button
            onClick={() => handleAction('WARNING_UPLOAD')}
            className="flex flex-col items-center justify-center w-20 h-20 bg-black/40 hover:bg-orange-500/20 border border-white/10 hover:border-orange-500 text-orange-400 rounded transition-all group"
          >
            <AlertTriangle size={24} className="mb-1 group-hover:scale-110 transition-transform" />
            <span className="text-[10px] font-bold">WARNING</span>
          </button>

          <button
            onClick={() => handleAction('TICKET_UPLOAD')}
            className="flex flex-col items-center justify-center w-20 h-20 bg-black/40 hover:bg-red-500/20 border border-white/10 hover:border-red-500 text-red-400 rounded transition-all group"
          >
            <FileText size={24} className="mb-1 group-hover:scale-110 transition-transform" />
            <span className="text-[10px] font-bold">TICKET</span>
          </button>
        </div>
      </div>
    </div>
  );
}
